from collections import Counter,deque

def comps(g):
 H,W=len(g),len(g[0]); seen=set(); out=[]
 for r in range(H):
  for c in range(W):
   col=g[r][c]
   if not col or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and g[nx][ny]==col:
      seen.add((nx,ny));q.append((nx,ny))
   out.append((col,cells))
 return out
